class Solution {
    public int minImpossibleOR(int[] nums){
        Set<Integer> values=new HashSet<>();
        for(int value:nums)values.add(value);
        int candidate=1;
        while(values.contains(candidate))candidate<<=1;
        return candidate;
    }
}

code.kotlin:
class Solution {
    fun minImpossibleOR(nums:IntArray):Int{
        val values=nums.toHashSet();
        var candidate=1;
        while(candidate in values)candidate=candidate shl 1;
        return candidate
    }
}

code.cpp:
class Solution {
    public:int minImpossibleOR(vector<int>& nums){
        unordered_set<int> values(nums.begin(),nums.end());
        int candidate=1;
        while(values.count(candidate))candidate<<=1;
        return candidate;
    }
};
